/**
 * Single presentation mapping for every public and admin category surface.
 *
 * None of these marks ship in the site's web fonts. Every loaded family is
 * extended with a same-origin face for exactly these codepoints
 * (styles/category-glyph-faces.css, generated by
 * scripts/build-category-glyph-font.mjs) so devices without a symbol font
 * still paint them. Adding or changing a glyph here means re-running that
 * script; its unit test fails until the fonts cover the new codepoint.
 */
export const CATEGORY_GLYPHS: Record<string, string> = {
  "community-events": "◈",
  "encoding-codecs": "◇",
  "general-tools": "◆",
  "infrastructure-delivery": "▣",
  "intro-learning": "▤",
  "media-tools": "▥",
  "players-clients": "▶",
  "protocols-transport": "⟁",
  "standards-industry": "◉",
};

/** "Protocols & Transport" and "protocols-transport" both → "protocols-transport". */
export function categorySlug(category?: string | null): string {
  return (category ?? "").trim().toLowerCase().replace(/&/g, "")
    .replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

export function categoryGlyph(category?: string | null): string {
  return CATEGORY_GLYPHS[categorySlug(category)] ?? "◆";
}
